package aws

type (
	rateInfo struct {
		Region string  `json:"Rg"`
		Typ    string  `json:"T"`
		Plat   string  `json:"P"`
		Terms  string  `json:"Tm"`
		Rate   float32 `json:"R"`
		Core   float32 `json:"C"`
		ECU    string  `json:"ECU"`
		Clock  string  `json:"Cl"`
		Proc   string  `json:"Pr"`
		Feat   string  `json:"Fe"`
		Mem    string  `json:"M"`
		Sto    string  `json:"St"`
		EBS    string  `json:"EBS"`
		Net    string  `json:"Nw"`
	}

	ebsRateInfo struct {
		Region string  `json:"Rg"`
		Typ    string  `json:"T"`
		SZrate float32 `json:"SZ"`
		IOrate float32 `json:"IO"`
	}

	snapRateInfo struct {
		Region string  `json:"Rg"`
		Typ    string  `json:"T"`
		SZrate float32 `json:"SZ"`
	}
)

